insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('01ad9fa7-487e-4a15-9efe-50998f9de4ee','00000000-0000-4000-8000-000000000102','740e71ad-966e-42e9-9cd8-e963b348333f','00000000-0000-4000-8000-0000000005a4','1','Navigating Setbacks','A missed week is data, not a verdict.','t','7',E'[{"id": "fcd66037-9b2d-4159-a157-c2e208007eff", "data": {"text": "Setbacks are part of the plan", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "1cee1dbc-6112-45cd-a4fa-cf38af6ef2df", "data": {"text": "Illness, travel, a brutal work stretch, a flat patch — every member hits them. A setback is information about your life this week, not a judgment on your worth or your progress. The skill is the recovery: reset at the very next session, and resist the urge to \\"make up\\" for lost time by doing too much. Overcompensating usually causes the next setback."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "7c66fb63-e6f4-4296-95cb-b681474d2e08", "data": {"prompt": "You missed a full week of training. What is the Built For Her way to respond?", "options": [{"id": "f4467bb3-f24c-4029-ad06-f849d97da91a", "text": "Reset at the next session and pick up the plan where it makes sense"}, {"id": "5afdf282-b51a-446c-a224-6fab59ffd552", "text": "Double next week to make up for it"}, {"id": "3eefdc30-53be-481d-9b57-794516295d05", "text": "Start the whole program over from scratch"}], "explanation": "Restart quickly and calmly. Compensating with extra volume tends to cause the next setback.", "correctOptionId": "f4467bb3-f24c-4029-ad06-f849d97da91a"}, "type": "knowledge_check", "position": "a2", "schemaVersion": 1}, {"id": "c2129788-0968-45f0-9137-35980a8d325e", "data": {"body": "Reset at the next session, not the next month. That single habit protects years of progress.", "tone": "info", "title": "The recovery is the skill"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:24:52.341865+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('076f8f08-2d7f-4160-aac6-1d27c7c6995a','00000000-0000-4000-8000-000000000102','c5a0c8f6-607f-4ad8-bb69-e5c48c7907fb','00000000-0000-4000-8000-0000000005a1','1','How Built For Her Works','The system behind your training.','t','8','[{"id": "8341b01c-c23d-4601-967b-6e03b16398f2", "data": {"text": "A coaching system, not a workout generator", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "6e7f1539-2bd5-4390-b45c-29ad56d2c73b", "data": {"text": "Built For Her follows a simple loop: we **assess** where you are, give you a **program** matched to it, **progress** that program as you adapt, and **adjust** based on how you respond. Nothing is random, and nothing is one-size-fits-all. Your job is to train consistently and tell us how it went; our job is to make the next step the right one."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "44603a50-d0a9-4eb9-9e98-0bfaa34b8dec", "data": {"rows": [{"id": "fed64e57-832d-4b56-900b-bcef1d6d9b2e", "left": "A progressive, coached plan", "right": "A random daily workout"}, {"id": "315fcad6-0116-4f44-a1a3-e84ce81835d2", "left": "Built around your life", "right": "Punishment for eating"}, {"id": "5c1d5131-fabb-4519-ab0c-aacd64a7d4b8", "left": "Focused on long-term strength", "right": "A 30-day quick fix"}], "leftTitle": "What Built For Her is", "rightTitle": "What it is not"}, "type": "comparison", "position": "a2", "schemaVersion": 1}, {"id": "609a62e5-b1dc-4335-8edc-64d6ad648e28", "data": {"body": "Assess → Program → Progress → Adjust. Every check-in feeds the next block. Consistency is what makes the loop work.", "tone": "success", "title": "The loop"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:19:30.440709+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('1068e06d-dd70-45e8-88a4-9ab051e38f42','00000000-0000-4000-8000-000000000102','99134308-702e-4bc8-9c52-e38a50192ccc','00000000-0000-4000-8000-0000000005a3','1','Protein','The repair material.','t','7','[{"id": "618ef935-edc2-4e84-9490-97bfc292ebe6", "data": {"text": "The one lever most worth getting right", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "9678d5e0-c7f0-4270-939a-5ed87e8d164d", "data": {"text": "Protein is the raw material your body uses to repair and build. For anyone training for strength, it is the highest-return nutrition habit: it supports recovery, helps you hold onto muscle (especially when eating less), and keeps you fuller. The practical version is simple — include a protein source at most meals and spread it across the day rather than cramming it into one."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "e0c1a2fe-04b7-4532-ba7e-0e1da1c109ea", "data": {"prompt": "Why is protein especially important for someone training for strength?", "options": [{"id": "94122a76-5d55-4184-b041-a934064e33fb", "text": "It supports recovery and helps preserve muscle, even in a calorie deficit"}, {"id": "91c633aa-51ea-40b6-91b3-c0176fdc6db7", "text": "It replaces the need for training"}, {"id": "057c204c-9431-4a85-8dc4-5a53dea5d335", "text": "It only matters right after a workout"}], "explanation": "Protein is the repair material. Spread across the day, it protects the muscle your training builds.", "correctOptionId": "94122a76-5d55-4184-b041-a934064e33fb"}, "type": "knowledge_check", "position": "a2", "schemaVersion": 1}, {"id": "90158932-6b0b-47a5-8233-7ee839a53d30", "data": {"body": "A protein source at most meals. You do not need to weigh every gram — you need a habit you can repeat.", "tone": "info", "title": "Keep it practical"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('231e7928-6b94-4fb6-b07a-d816d45bdfef','00000000-0000-4000-8000-000000000102','8c6691c6-499f-4aa7-b808-85d18c901a83','00000000-0000-4000-8000-0000000005a4','1','Mindset','How you talk to yourself matters.','t','7',E'[{"id": "ed8b85cd-0538-41ef-8b30-60eb58d0ddc5", "data": {"text": "Coach yourself the way we coach you", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "2314e773-78b5-425d-b133-3f94fc0da3d3", "data": {"text": "The voice in your head is a training variable too. Treating strength as a long-term investment — something you build over years, not weeks — takes the pressure off any single session. And the evidence is clear enough to say plainly: self-compassion outperforms self-criticism for sticking with hard things. Talk to yourself like someone you are coaching, not someone you are punishing."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "b48b5ec9-26fb-4d29-b8fb-50b4b76cbf87", "data": {"rows": [{"id": "ee66f1b1-7050-4adc-8a39-24a86d523aab", "left": "\\"I blew it, why bother\\"", "right": "\\"One week off, back on now\\""}, {"id": "4e62d068-2d76-4014-be58-4f1e53aaa0e3", "left": "All-or-nothing", "right": "Something beats nothing"}, {"id": "990072f2-1100-43ba-ac63-49443e1f0c3f", "left": "Shame, then avoidance", "right": "Honesty, then a next step"}], "leftTitle": "Harsh inner critic", "rightTitle": "Supportive coach voice"}, "type": "comparison", "position": "a2", "schemaVersion": 1}, {"id": "961f688a-d30b-41cb-b64c-c47096ef3715", "data": {"body": "You are not behind. You are building something durable. Play the long game.", "tone": "note", "title": "Strength is a long-term investment"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:24:52.341865+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('27934093-8ff6-4678-bf08-7d5de016df12','00000000-0000-4000-8000-000000000102','1b64d882-43ff-4746-ada0-dcb00742d45b','00000000-0000-4000-8000-0000000005a5','1','Plateau Management','When progress stalls.','t','8','[{"id": "701816f0-54f4-4c09-b3d7-009457c6cc7a", "data": {"text": "Plateaus are normal — and solvable", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "03bc1833-b1eb-43c1-aeb3-2bd23f74fef7", "data": {"text": "Progress is never perfectly linear. When the numbers stall, resist the urge to blow everything up. Check the boring fundamentals first: Have you actually been consistent? Are you sleeping and recovering? Are you eating enough, with enough protein? More often than not, a plateau is a recovery or consistency problem wearing a training costume. Once the basics are solid, your coach adjusts one variable and progress resumes."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "5df5ceb6-d803-42b7-9e78-3011362baf28", "data": {"prompt": "Your lifts have stalled for a couple of weeks. What should you check FIRST?", "options": [{"id": "856173e2-5937-4318-8035-d4a351f5dea8", "text": "Consistency, recovery, and nutrition — the fundamentals"}, {"id": "8cf44559-f7ab-4589-bd00-d7538f9ee56c", "text": "Overhaul the entire program immediately"}, {"id": "80e8c724-e3cf-446b-a31b-298ab4ac8449", "text": "Add a second daily session"}], "explanation": "Most plateaus trace back to recovery or consistency. Fix the foundation before changing the training.", "correctOptionId": "856173e2-5937-4318-8035-d4a351f5dea8"}, "type": "knowledge_check", "position": "a2", "schemaVersion": 1}, {"id": "d7a4b1a9-4c7a-475d-8057-25db7210ef19", "data": {"body": "Sometimes the plateau breaks simply because you kept showing up and recovering. Give the basics a chance to work.", "tone": "note", "title": "Patience is a tactic"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('3e5b34cd-fc8b-450c-9c09-4b96732f715f','00000000-0000-4000-8000-000000000102','8b67c08c-f518-4e44-b35c-b58a3f49f635','00000000-0000-4000-8000-0000000005a4','1','Consistency','Consistency beats perfection.','t','7','[{"id": "dbbcf8c3-3b4f-4790-9e83-6ef60453ef95", "data": {"text": "Consistency beats perfection", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "171f79eb-8b9c-4c30-b52e-cdf546fae72b", "data": {"text": "The members who transform are almost never the ones who never miss. They are the ones who restart quickly. One imperfect week changes nothing if the next week is on. Progress is the sum of many ordinary weeks, not a few heroic ones — which is good news, because ordinary is repeatable."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "a14223de-c0fe-4cc9-8443-636f1c96fb49", "data": {"body": "Decide the smallest version of training you will still do when life is busy. A minimum you can always hit keeps the habit alive through hard stretches.", "tone": "info", "title": "Define your minimum week"}, "type": "callout", "position": "a2", "schemaVersion": 2}, {"id": "e155c9c9-dc45-4f1d-b27c-2ffb614d38a6", "data": {"text": "Aim for your full plan; protect your minimum. As long as the streak of *showing up* stays intact, the results keep compounding."}, "type": "rich_text", "position": "a3", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:24:52.341865+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('4e72521d-2e99-4814-ae55-e0c5b8c8c6f7','00000000-0000-4000-8000-000000000102','0166c86c-2407-40b2-a32c-6f74a40e20b8','00000000-0000-4000-8000-0000000005a1','1','Expectations & Standards','What a good week looks like.','t','7','[{"id": "016019fd-5e72-4797-98fc-83a0d30b07bd", "data": {"text": "Clear standards make progress simple", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "dce1cb68-dbe8-4ceb-8b73-ec54524715bd", "data": {"text": "You will never have to guess whether you are doing enough. A good Built For Her week is simple and repeatable: complete your planned sessions, eat enough protein most days, and note how you felt so your coach can adjust. These are a floor to stand on, not a bar to fear — hit them most weeks and progress takes care of itself."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "e5478d18-114f-4cf8-9e88-3af66f895c9c", "data": {"text": "We hold these standards *with* you, not over you. A missed session is information, not a verdict. The standard is not perfection — it is showing up often enough that the training compounds."}, "type": "rich_text", "position": "a2", "schemaVersion": 1}, {"id": "0cb308e8-5db1-43e9-ac51-20eb57b3b9e9", "data": {"prompt": "Which best describes a good Built For Her week?", "options": [{"id": "835b3a44-a389-4cd3-89a0-405eba315a9f", "text": "Complete your planned sessions, hit protein most days, and note how you felt"}, {"id": "aa73e63c-144e-4bd1-b1a6-39b8f920d623", "text": "Train every day until you are exhausted"}, {"id": "b26478c9-a033-4c00-aeee-8c29779b2782", "text": "Eat as little as possible and never miss"}], "explanation": "Simple, repeatable standards beat heroic weeks you cannot sustain. Consistency is the goal.", "correctOptionId": "835b3a44-a389-4cd3-89a0-405eba315a9f"}, "type": "knowledge_check", "position": "a3", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:19:30.440709+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('550321de-07a3-4ee0-9384-e5d080ab0660','00000000-0000-4000-8000-000000000102','b28095a3-eb30-4da8-8f40-9248df9cbaf5','00000000-0000-4000-8000-0000000005a2','1','Technique Before Load','Earn the right to add weight.','t','8','[{"id": "164851f9-e26e-4f07-96e5-dfa77a4e3adf", "data": {"text": "Skill first, weight second", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "5fee31e6-7e13-41fe-b900-c3c55acf5dd1", "data": {"text": "Every lift is a skill. When you groove a clean pattern first, adding load later is safe *and* far more effective — the weight goes where it should. Chasing heavy numbers before the pattern is solid usually buys short-term ego and long-term frustration. We would rather build something that lasts."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "4da822f5-a527-42f9-afcf-8d4542f425cd", "data": {"rows": [{"id": "51da96d3-dda6-48b7-8f80-78f0937f92b9", "left": "Numbers today", "right": "Progress that keeps coming"}, {"id": "14440443-ea51-4423-9e10-91365c93b90b", "left": "Form breaks under load", "right": "Load rides a clean pattern"}, {"id": "3f1b56ca-f7af-40b6-90af-6167e6857793", "left": "Higher injury risk", "right": "Durable, repeatable strength"}], "leftTitle": "Chasing weight", "rightTitle": "Building skill"}, "type": "comparison", "position": "a2", "schemaVersion": 1}, {"id": "180e7846-a95f-4edb-a243-3bd77d75fb9f", "data": {"body": "If quality is slipping, the weight is too high for today. Own the movement, then load it.", "tone": "note", "title": "Technique before load"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('561724d2-20aa-4ef0-af35-29c240c9d839','00000000-0000-4000-8000-000000000102','d7508248-7ba8-4b85-a662-ed5aeb519f35','00000000-0000-4000-8000-0000000005a3','1','Calories','Energy in and out, held gently.','t','8','[{"id": "7e53cdf5-3f66-4e0f-9906-cbdef31dfe19", "data": {"text": "Calories are energy, not a verdict", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "7f108741-b4e6-4d4c-8288-78496e5afb61", "data": {"text": "A calorie is a unit of energy — nothing more moral than that. Whether you are building strength, maintaining, or losing fat, your energy intake sets the backdrop. The most common mistake we see is *under*-eating: cutting too hard, too fast, which drains training quality, recovery, and mood. We would rather fuel the work than starve it."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "31169043-f502-49dc-8824-e074f18450a8", "data": {"rows": [{"id": "5b54c2a2-c95b-4507-b44a-24b2af6f451b", "left": "Flat, weak sessions", "right": "Energy to progress"}, {"id": "52348a0e-d5f9-416f-a05a-47da3477bbfa", "left": "Poor recovery & sleep", "right": "Better recovery"}, {"id": "34fa0f53-6863-4b87-89ba-c34ae098972b", "left": "Muscle lost with fat", "right": "Strength preserved"}], "leftTitle": "Chronic under-fueling", "rightTitle": "Fueling to train"}, "type": "comparison", "position": "a2", "schemaVersion": 1}, {"id": "7a413ad5-f852-4c6c-a05f-9fb1c3ce8f41", "data": {"body": "Aggressive cuts feel productive and usually are not. Slower and fed beats fast and depleted.", "tone": "warning", "title": "Eat enough to train"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('643b5722-f09a-4264-9242-01b0824a147b','00000000-0000-4000-8000-000000000102','d5c294b8-b843-4062-8f37-3574bcf9980a','00000000-0000-4000-8000-0000000005a3','1','Strength Nutrition','Eat like someone who trains.','t','8','[{"id": "11307b2d-2d97-4f86-8d20-1acfb66346aa", "data": {"text": "Eat like someone who trains", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "2e256247-ece8-48c1-8673-a98a5a651bea", "data": {"text": "Once the basics are in place, fueling around training makes sessions feel better and recovery smoother: enough carbohydrate to power your work, protein through the day to rebuild, and a real meal within a few hours of finishing. None of this needs to be precise. A fed, consistent lifter out-progresses a perfectly-tracked one who cannot sustain it."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "e38f563e-959f-4b51-ac66-b7348e163d02", "data": {"prompt": "What is one fueling habit you could build this week — a protein-forward breakfast, a pre-training snack, or a post-session meal? Pick one and make it easy.", "guidance": "One habit, made obvious and repeatable. Then finish the short check below."}, "type": "reflection", "position": "a2", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('68e34ae7-4006-4f44-a9f4-017755cddc51','00000000-0000-4000-8000-000000000102','d925ea65-bffa-4d12-9d05-baf67240ada1','00000000-0000-4000-8000-0000000005a2','1','Progressive Overload','Doing a little more, over time.','t','8','[{"id": "0bd48609-59df-4c3e-b417-2a4990c37bf6", "data": {"text": "Progress is earned a little at a time", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "16a8d148-1e39-45fd-bd22-43e6ae9f40e4", "data": {"text": "Progressive overload means gradually increasing the demand you place on your body. Adding weight is only one lever. You can also add reps, add a set, improve range of motion, control tempo, or simply perform the same work with cleaner technique. The best lever is the one you can win at *this* week."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "8aa16027-9e8c-4af0-862b-b9c9cc213d40", "data": {"prompt": "Which statement about progressive overload is TRUE?", "options": [{"id": "bd55546a-2cd8-4fb4-b915-27f9e5c1d8f1", "text": "It can be reps, sets, range, tempo, or quality — not just heavier weight"}, {"id": "a9fa7c53-2792-43e9-aba5-53faa5e0cd14", "text": "It only counts if you add weight every session"}, {"id": "06941907-e0f9-4fc2-a15a-839d554da1a6", "text": "It means training to failure every set"}], "explanation": "Load is one lever among several. Smart progression picks the lever you can repeat, so the gains stick.", "correctOptionId": "bd55546a-2cd8-4fb4-b915-27f9e5c1d8f1"}, "type": "knowledge_check", "position": "a2", "schemaVersion": 1}, {"id": "b2267461-ce97-4df3-876c-4f2f529dddc8", "data": {"body": "A tiny amount more than last time, most weeks, becomes remarkable over a year. That is the whole game.", "tone": "success", "title": "Small steps, repeated"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('6e90ec61-03e9-4d54-9066-d51fd77df5b8','00000000-0000-4000-8000-000000000102','2323d52b-bbcd-4083-b173-07efb2570b16','00000000-0000-4000-8000-0000000005a4','1','Stress Management','Stress is a training variable.','t','7',E'[{"id": "140df536-e65d-4858-b253-eaeeffb9269a", "data": {"text": "Life stress and training share a bucket", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "307d5a86-2425-491e-8647-4a9409d44ad1", "data": {"text": "Your body does not neatly separate a hard week at work from a hard week of training — the stress pools in the same bucket. In high-stress stretches, expect training to feel heavier and recovery to lag. That is normal, and it is a reason to *adjust*, not to quit. Readiness informs the plan: a lighter, completed session in a stressful week still counts."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "0fbc8f80-c482-4f7a-924b-10f1c1cd168d", "data": {"prompt": "Think of your last genuinely stressful week. How did training feel, and what would \\"adjust, do not quit\\" have looked like — a lighter session, a walk, an earlier night?", "guidance": "Name what you would do differently next time the bucket is full."}, "type": "reflection", "position": "a2", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:24:52.341865+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('722ac0c1-b8a4-4341-aead-652cfb54aa90','00000000-0000-4000-8000-000000000102','8b2cffb1-15ee-4201-a641-c4c5a4f4fe85','00000000-0000-4000-8000-0000000005a5','1','Tracking Progress','Measure what matters.','t','8',E'[{"id": "232256c5-c965-4bde-aaf1-a6aa7fb0faf7", "data": {"text": "The scale is one noisy signal", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "ac8c8ddb-e57f-4fda-bc22-ba83ed923815", "data": {"text": "Bodyweight bounces daily with water, food, sleep, and hormones — reading a single morning as \\"progress\\" or \\"failure\\" will only mislead you. Zoom out and watch trends across weeks, and track more than one thing. Strength in the gym, how your clothes fit, energy and mood, and photos over time often tell a truer story than the scale alone."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "64e837bc-a91d-4c78-9c81-153847bef8fc", "data": {"cards": [{"id": "b603b81a-7144-4d70-bc76-8acf3dcfe045", "back": "Lifting more over time is direct evidence your training is working — often the earliest signal.", "front": "Strength"}, {"id": "f87c631f-c8be-44c5-8bf7-74e7bf6744b0", "back": "Composition can change while the scale barely moves. Fit catches what weight misses.", "front": "How clothes fit"}, {"id": "e3be9e73-6d5d-4c4c-bda1-5c128d981e46", "back": "Feeling stronger and steadier day to day is real progress, even before it shows up elsewhere.", "front": "Energy & mood"}, {"id": "ef2d4e4e-72e0-4392-8403-9b13b23bea85", "back": "Judge the 4-week direction, not this morning. One data point is noise; the trend is signal.", "front": "Trends, not days"}]}, "type": "flashcards", "position": "a2", "schemaVersion": 1}, {"id": "71e9b001-ec59-4f77-b5c7-37a7a145f184", "data": {"body": "Track a few honest signals and read the trend. Progress is earned slowly and seen best from a distance.", "tone": "info", "title": "Zoom out"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('8175607c-d069-4e91-8e78-964c5d5da076','00000000-0000-4000-8000-000000000102','94dd1076-3e4d-4d0f-be83-bfd9b472acbc','00000000-0000-4000-8000-0000000005a2','1','Recovery Fundamentals','Recovery is training.','t','8','[{"id": "6302802d-f411-4dc1-8e67-f34001724691", "data": {"text": "You grow between sessions", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "ba4cb760-15e9-467e-aad5-e313ee9b9af1", "data": {"text": "Training is the stimulus; recovery is where the adaptation actually happens. Sleep, food, rest days, and managing stress are not the opposite of training — they *are* part of it. More training on top of poor recovery does not speed things up; it digs a hole. Treat recovery as a skill you practice, not a reward you earn."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "1ece5f70-2264-4696-b210-042a17e14ec9", "data": {"prompt": "Of sleep, nutrition, rest, and stress — which is your weakest recovery link right now? What is one small change you could make this week?", "guidance": "Name the link and one concrete, doable change. Small counts."}, "type": "reflection", "position": "a2", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('97fcf08b-fe71-44af-8622-da46dabf6351','00000000-0000-4000-8000-000000000102','00a408f2-4370-4958-83a0-1d7b58930792','00000000-0000-4000-8000-0000000005a4','1','Habit Formation','Make the right thing easy.','t','8',E'[{"id": "cecbe4f2-dc84-4412-b87f-b0dc6ff308d5", "data": {"text": "Design the behaviour, do not rely on willpower", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "5b91296a-7cdc-4b34-83b1-535917963ca9", "data": {"text": "Motivation comes and goes; habits carry you when it is gone. The trick is to make the behaviour you want *easy* and *obvious*, and to attach it to something you already do. You are not weak when motivation dips — you just have not yet designed the habit so it barely needs motivation."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "cdd6d00a-3277-4dd0-b0db-db3ee367bee8", "data": {"cards": [{"id": "df12a0c3-b424-4d9d-a987-a04d98a6b67e", "back": "Lay your kit out the night before. Put the cue where you cannot miss it.", "front": "Make it obvious"}, {"id": "7b025394-8da7-4bb9-9cdd-cc862e9aaec9", "back": "Shrink the first step. \\"Change into gym clothes\\" is easier to start than \\"train for an hour.\\"", "front": "Make it easy"}, {"id": "f214c61a-78ab-473e-899f-73dff441855d", "back": "Attach training to an existing routine: \\"After I drop the kids, I train.\\" The old habit cues the new one.", "front": "Habit stacking"}, {"id": "97632cbd-44e5-40b6-8e4a-bc07f0732c76", "back": "Tick it off, log it, notice the win. A little closure makes the habit want to repeat.", "front": "Make it satisfying"}]}, "type": "flashcards", "position": "a2", "schemaVersion": 1}, {"id": "2d321405-42eb-4238-b2bf-d30382c44ac4", "data": {"body": "Every obstacle you remove ahead of time is one you do not have to overcome tired. Set future-you up to win.", "tone": "success", "title": "Reduce friction"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:24:52.341865+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('a074f828-2383-493f-9146-e3e536a4e0cb','00000000-0000-4000-8000-000000000102','d5ebc33f-e801-4c6f-b703-c230420a3bed','00000000-0000-4000-8000-0000000005a2','1','Training Principles','The ideas behind every good program.','t','8','[{"id": "0c77c10b-be14-4bee-b48b-628089cb59f3", "data": {"text": "A few principles explain almost everything", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "06174e24-b08b-469a-9fb4-931c7ec9b5ee", "data": {"text": "You do not need to memorize training science. A handful of principles quietly shape every session your coach programs. Understand these and the plan stops feeling arbitrary — you can see the logic underneath it."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "7489bcd3-6b66-4f1f-b85a-85df2fafea76", "data": {"cards": [{"id": "d72839c4-e5ce-4322-a657-0cef5f875d57", "back": "Adaptation needs a reason. We gradually ask a little more of you so your body has something to adapt to.", "front": "Overload"}, {"id": "c3d08434-d328-42c4-a770-5d2918a3afef", "back": "You get better at what you practice. Training targets the qualities your goal actually needs.", "front": "Specificity"}, {"id": "60a73ef1-a5a7-4a86-bd64-f178d3ee9e11", "back": "The same plan lands differently on different people. We adjust to how you respond, not a textbook average.", "front": "Individuality"}, {"id": "ad75cd22-e143-468c-9447-be2f003854f4", "back": "Adaptation happens between sessions. Without recovery, overload is just fatigue.", "front": "Recovery"}]}, "type": "flashcards", "position": "a2", "schemaVersion": 1}, {"id": "acd87753-8fe6-4cac-9bcd-2b22a1f05e35", "data": {"body": "Ask a little more, recover well, repeat. Strength is a long-term investment, not a sprint.", "tone": "info", "title": "The throughline"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('a20ac5bf-53fb-4b1f-a8d3-4213405970b2','00000000-0000-4000-8000-000000000102','a8b959cc-5b0e-4d6d-a5d3-0108f7d5d9fc','00000000-0000-4000-8000-0000000005a2','1','Deloads','Planned easier weeks that make you stronger.','t','8','[{"id": "c43b3041-3499-4e62-9af8-fad72c65e577", "data": {"text": "Backing off on purpose", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "88fa4fed-7f23-4845-85d6-41a624ca9b66", "data": {"text": "A deload is a planned lighter week — less weight, fewer sets, or both. It is not a setback or a sign of weakness; it is the week your body catches up and turns training into strength. Skilled lifters deload *before* they are broken, not after. When your program calls for one, trust it and let your body absorb the work."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "1b8c0a5c-fc70-49a5-94d0-c4196cc3f49f", "data": {"body": "Easy on purpose. If you finish the week itching to train, the deload did its job. You will often come back stronger.", "tone": "note", "title": "How a deload should feel"}, "type": "callout", "position": "a2", "schemaVersion": 2}, {"id": "cd32e200-c3c5-488b-9b69-7177b5450afe", "data": {"text": "Signs a deload is near: nagging aches, stalled lifts, poor sleep, low motivation. Sometimes the fastest way forward is a step back. Finish this program with the short check below."}, "type": "rich_text", "position": "a3", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('b54f7a02-457f-406d-b53c-64b7734ba285','00000000-0000-4000-8000-000000000102','a5c0bbb7-03c0-407a-ae16-2976c389c504','00000000-0000-4000-8000-0000000005a1','1','Welcome','What this Academy is for, and how to use it.','t','6','[{"id": "e6037d58-f3a9-4bc7-8203-7c4f0ed67390", "data": {"text": "Welcome to Built For Her", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "515e100f-3650-4d81-be7a-2b865eef0951", "data": {"text": "This Academy is where the *why* behind your training lives. Your program tells you what to do each session; these short lessons explain the thinking, so you can train with confidence instead of guesswork. Read them at your own pace — a few minutes here saves hours of second-guessing later."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "fd655089-c46d-4b9a-b5e6-851d20f77bd0", "data": {"text": "You do not need prior experience. We build from the ground up, one idea at a time, and every lesson connects back to the same principles you will see in your coaching. Start at the top and work down — the order is intentional."}, "type": "rich_text", "position": "a2", "schemaVersion": 1}, {"id": "59ab23d5-bd3a-46a3-b6d4-d5a8b80cb74d", "data": {"body": "Short lessons, in order. Read, reflect, and return whenever you want a refresher. Nothing here is a test to pass — it is coaching you can revisit.", "tone": "info", "title": "How to use the Academy"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:19:30.440709+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('c07be394-752c-45f0-a666-10a01133e6b3','00000000-0000-4000-8000-000000000102','7a7a7977-d011-435f-91dd-3aff6aa14a3d','00000000-0000-4000-8000-0000000005a5','1','Holidays','Enjoy the holidays without derailing.','t','6','[{"id": "a69206ae-e292-4e72-b60b-1d7d44ea0c29", "data": {"text": "Live your life — then come back", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "0279d43f-7f68-4bb5-8115-93cd4a9868e0", "data": {"text": "Holidays are for living, and food is part of that. One weekend, one celebration, one big meal will not undo months of consistency — but the *story* you tell yourself about it can. The members who stay on track do not eat perfectly through the holidays; they simply return to normal quickly afterward, without guilt or punishment. Anchor to two habits when everything else is loose: enough protein and a daily walk."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "8ac35a9a-8d9a-4367-9b4f-79b2c3b9bbfe", "data": {"body": "Enjoy it, then return to your normal at the very next meal or session. No compensating, no starting over.", "tone": "success", "title": "The bounce-back is what counts"}, "type": "callout", "position": "a2", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('c108ed89-b0af-408b-a999-a29e1f813cf2','00000000-0000-4000-8000-000000000102','198a5d91-9a41-46e7-a80c-93b07fdd2811','00000000-0000-4000-8000-0000000005a5','1','Graduation','You have built your foundation.','t','7','[{"id": "07c9c89e-f4d6-4a8f-b3a4-06770f6ba8ca", "data": {"text": "You have built your foundation", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "36689acf-9d80-4a47-bc6c-a5e4d8e7fca7", "data": {"text": "You now know the *why* behind your training. You understand how strength is built — a little more over time, technique before load — that recovery and nutrition are part of the work, and that consistency, not perfection, is what compounds. Most importantly, you know how to handle the hard weeks: adjust, do not quit, and reset at the next session."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "7817e666-a136-4a56-81d8-ec80385380ea", "data": {"text": "Carry these principles forward: **progress is earned, technique before load, consistency beats perfection, nutrition supports performance, recovery is training, and strength is a long-term investment.** Everything ahead is just applying them, week after week. Finish the short final check below to earn your Strong Foundations credential."}, "type": "rich_text", "position": "a2", "schemaVersion": 1}, {"id": "e8e53b37-32e4-4186-bedd-8ce864bc47a8", "data": {"prompt": "Which one Built For Her principle will you carry into your next month of training, and how will it change one thing you do?", "guidance": "Name the principle and the single change. That is your graduation intention."}, "type": "reflection", "position": "a3", "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('d3604a24-023e-4816-b103-7effc33dfb80','00000000-0000-4000-8000-000000000102','e51a3f64-a274-40c4-9541-cf8485a427b5','00000000-0000-4000-8000-0000000005a5','1','Travel','Training that travels with you.','t','7','[{"id": "8f1ca0ec-ec30-4b92-9300-0b232384b60c", "data": {"text": "A trip is not a training write-off", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "ee23a61e-b78d-4f74-960e-f09bab370363", "data": {"text": "Travel is where good intentions usually die — and they do not have to. The goal on the road is not progress; it is *maintenance*: keep the habit alive with whatever you have. A short bodyweight or band session, a daily walk, and protein-forward meals will hold almost everything you have built. Doing a little keeps the door open; doing nothing is what actually costs you."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "5b5b069a-8a43-4c21-bb7e-345e98ede9f4", "data": {"note": "Decide it now, while it is easy — not at 9pm in an unfamiliar city.", "text": "Before your next trip, write your travel minimum: one 15-minute session you can do in a hotel room and a daily step target."}, "type": "action_step", "position": "a2", "schemaVersion": 1}, {"id": "5a23ea0d-d492-4a10-b3f4-49d82febd8de", "data": {"body": "You cannot always progress on the road. You can almost always maintain — and maintaining is how you come back without starting over.", "tone": "info", "title": "Maintenance is a win"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('d5f8b360-8c6a-43be-809c-fa4afd568181','00000000-0000-4000-8000-000000000102','72da4441-bfdb-4af4-81ef-3fbcf3e7b2c5','00000000-0000-4000-8000-0000000005a3','1','Nutrition Foundations','Food is fuel, not a moral test.','t','8','[{"id": "5f0934b1-95bb-4206-a6fc-67ffd093a368", "data": {"text": "Fuel, not a moral test", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "e1c647f8-0071-4e4c-a680-37caebc3546b", "data": {"text": "Nutrition at Built For Her has one job: to support your training and recovery. Food is not good or bad, and eating is not something to earn back with exercise. You do not need a perfect diet — you need a mostly-consistent one built on a few levers: enough energy, enough protein, mostly whole foods, and enough water."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "4afa2135-e814-4f10-8400-d6597c1c9235", "data": {"cards": [{"id": "e553d945-8368-478e-8ed8-094bf2e1235e", "back": "Calories are fuel for training and recovery. Too little, for too long, stalls progress.", "front": "Energy"}, {"id": "4fd38bcc-fe9e-4f20-ac8a-427599dad925", "back": "The building block for repair and holding muscle. The lever most worth getting right.", "front": "Protein"}, {"id": "536fe1f5-13ae-466d-86cc-04e6ea875e58", "back": "Mostly minimally-processed foods make hitting the other levers easier and keep you full.", "front": "Whole foods"}, {"id": "b597fc57-5e24-4611-915a-510055ace8de", "back": "Even mild dehydration dulls performance. Water first, consistently.", "front": "Hydration"}]}, "type": "flashcards", "position": "a2", "schemaVersion": 1}, {"id": "c54a3bfa-66e6-491d-8f44-7eabab578247", "data": {"body": "Get the levers roughly right, most days. Consistency beats a perfect plan you cannot keep.", "tone": "success", "title": "Nutrition supports performance"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
insert into public.lesson_versions (id,organization_id,lesson_id,course_id,version_number,title,summary,required,estimated_minutes,blocks,published_by,published_at) values ('fa9f14e9-b8c7-4a8e-800f-9c41f7b839c0','00000000-0000-4000-8000-000000000102','cf752772-8d41-4387-b4b6-3c5543b348e2','00000000-0000-4000-8000-0000000005a2','1','Sleep','Your highest-leverage recovery tool.','t','7','[{"id": "674f111c-a903-43ee-96df-92cbc0731932", "data": {"text": "Sleep does the quiet work", "level": 2}, "type": "heading", "position": "a0", "schemaVersion": 1}, {"id": "e879f5d2-6903-4a46-956d-0f2978ec9054", "data": {"text": "If recovery had a single highest-leverage habit, it would be sleep. It shapes how you adapt to training, how hungry you feel, your mood, and how well you perform in the gym. You do not need perfect sleep — you need *enough*, *consistently*. A regular sleep and wake time often helps more than any supplement."}, "type": "rich_text", "position": "a1", "schemaVersion": 1}, {"id": "a3439bd5-a4df-45e8-94ad-5c23781d0508", "data": {"cards": [{"id": "e5588445-47c5-49bf-96e9-0d6cda3ef684", "back": "Most people do best with 7–9 hours. Chronic short sleep blunts recovery and appetite control.", "front": "Enough"}, {"id": "69944958-f2f5-4df4-a1af-60766a9c91f3", "back": "Similar sleep and wake times steady your body clock — often more useful than one long catch-up night.", "front": "Consistent"}, {"id": "48f7e171-241f-4f56-a260-e823b631fdec", "back": "A dim, screen-light last 30 minutes signals your body it is time. Small routine, real payoff.", "front": "Wind-down"}]}, "type": "flashcards", "position": "a2", "schemaVersion": 1}, {"id": "b0a7b091-6561-487d-bc89-5935623c6b4b", "data": {"body": "Chase better sleep before chasing supplements. It is cheaper and works better.", "tone": "info", "title": "Protect the basics first"}, "type": "callout", "position": "a3", "schemaVersion": 2}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.course_versions (id,organization_id,course_id,version_number,title,summary,structure,completion_rule,published_by,published_at) values ('29c22ed6-e2ea-4906-8d89-2b70059dde71','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-0000000005a3','1','Nutrition Foundations','Fueling strength and recovery.','{"modules": [{"title": "Nutrition Basics", "lessons": [{"title": "Nutrition Foundations", "lessonId": "72da4441-bfdb-4af4-81ef-3fbcf3e7b2c5", "position": "a0", "required": true, "versionNumber": 1, "lessonVersionId": "d5f8b360-8c6a-43be-809c-fa4afd568181"}, {"title": "Calories", "lessonId": "d7508248-7ba8-4b85-a662-ed5aeb519f35", "position": "a1", "required": true, "versionNumber": 1, "lessonVersionId": "561724d2-20aa-4ef0-af35-29c240c9d839"}, {"title": "Protein", "lessonId": "99134308-702e-4bc8-9c52-e38a50192ccc", "position": "a2", "required": true, "versionNumber": 1, "lessonVersionId": "1068e06d-dd70-45e8-88a4-9ab051e38f42"}], "moduleId": "76fa9b2b-582a-449d-8aa1-1c04f9e7cbe6", "position": "a0"}, {"title": "Fueling Strength", "lessons": [{"title": "Strength Nutrition", "lessonId": "d5c294b8-b843-4062-8f37-3574bcf9980a", "position": "a0", "required": true, "versionNumber": 1, "lessonVersionId": "643b5722-f09a-4264-9242-01b0824a147b"}], "moduleId": "ae753b82-a5e4-4294-b187-46633747b9de", "position": "a1"}], "schemaVersion": 1}'::jsonb,'{"type": "all_required_lessons", "schemaVersion": 1}'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
insert into public.course_versions (id,organization_id,course_id,version_number,title,summary,structure,completion_rule,published_by,published_at) values ('55c13bad-a45c-49cf-9b3a-a4575336f0c6','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-0000000005a2','1','Training Foundations','How training works and how you get stronger.','{"modules": [{"title": "Training Principles", "lessons": [{"title": "Training Principles", "lessonId": "d5ebc33f-e801-4c6f-b703-c230420a3bed", "position": "a0", "required": true, "versionNumber": 1, "lessonVersionId": "a074f828-2383-493f-9146-e3e536a4e0cb"}, {"title": "Progressive Overload", "lessonId": "d925ea65-bffa-4d12-9d05-baf67240ada1", "position": "a1", "required": true, "versionNumber": 1, "lessonVersionId": "68e34ae7-4006-4f44-a9f4-017755cddc51"}, {"title": "Technique Before Load", "lessonId": "b28095a3-eb30-4da8-8f40-9248df9cbaf5", "position": "a2", "required": true, "versionNumber": 1, "lessonVersionId": "550321de-07a3-4ee0-9384-e5d080ab0660"}], "moduleId": "14fbe4fa-cc01-4ea6-a33c-52134c8619d8", "position": "a0"}, {"title": "Recovery", "lessons": [{"title": "Recovery Fundamentals", "lessonId": "94dd1076-3e4d-4d0f-be83-bfd9b472acbc", "position": "a0", "required": true, "versionNumber": 1, "lessonVersionId": "8175607c-d069-4e91-8e78-964c5d5da076"}, {"title": "Sleep", "lessonId": "cf752772-8d41-4387-b4b6-3c5543b348e2", "position": "a1", "required": true, "versionNumber": 1, "lessonVersionId": "fa9f14e9-b8c7-4a8e-800f-9c41f7b839c0"}, {"title": "Deloads", "lessonId": "a8b959cc-5b0e-4d6d-a5d3-0108f7d5d9fc", "position": "a2", "required": true, "versionNumber": 1, "lessonVersionId": "a20ac5bf-53fb-4b1f-a8d3-4213405970b2"}], "moduleId": "4de29152-878d-4ce7-a8c5-44927d65e237", "position": "a1"}], "schemaVersion": 1}'::jsonb,'{"type": "all_required_lessons", "schemaVersion": 1}'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
