insert into public.assessment_versions (id,organization_id,assessment_id,version_number,title,settings,items,published_by,published_at) values ('43f73ea5-f841-4fa3-b797-bfdb79c6c086','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-00000005a5a1','1','Strong Foundations — Final Check','{"scorePolicy": "highest", "schemaVersion": 1, "passingPercent": 70, "cooldownMinutes": 0}'::jsonb,'[{"id": "8ed7ee21-ffc7-4702-8423-03c41a53862b", "data": {"points": 10, "prompt": "Strength is built by…", "options": [{"id": "13cad9cb-3a10-4f76-82b4-841b1ac2dd09", "text": "Doing a little more over time, with technique before load"}, {"id": "64e9fc53-c00b-417a-8a20-391cc13c5e74", "text": "Training to exhaustion every day"}, {"id": "2abf906c-7047-4901-8959-c1ec2365148d", "text": "Eating as little as possible"}], "correctOptionId": "13cad9cb-3a10-4f76-82b4-841b1ac2dd09"}, "type": "multiple_choice", "position": "a0", "required": true, "schemaVersion": 1}, {"id": "61c0bdd5-ddcf-4776-b649-fb9e66d56689", "data": {"points": 5, "prompt": "Recovery — sleep, food, and rest — is part of training, not separate from it.", "correctValue": true}, "type": "true_false", "position": "a1", "required": true, "schemaVersion": 1}, {"id": "f8be131a-64a3-4096-a524-96d206e2a470", "data": {"points": 5, "prompt": "Consistency over time matters more than any single perfect week.", "correctValue": true}, "type": "true_false", "position": "a2", "required": true, "schemaVersion": 1}, {"id": "dc5e5ad1-39b6-4b28-bf87-d015bc597c53", "data": {"points": 10, "prompt": "After a missed week, the Built For Her response is to…", "options": [{"id": "f92cbbed-3731-4f5f-a02b-32ee5401c19d", "text": "Reset calmly at the next session"}, {"id": "068b69db-ca3b-4830-ab27-4f8eef8de73f", "text": "Punish yourself with double training"}, {"id": "0aefe16b-491e-46f5-bbd7-6c5d03d88544", "text": "Quit and start over"}], "correctOptionId": "f92cbbed-3731-4f5f-a02b-32ee5401c19d"}, "type": "multiple_choice", "position": "a3", "required": true, "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:26:38.211389+00') on conflict (id) do nothing;
insert into public.assessment_versions (id,organization_id,assessment_id,version_number,title,settings,items,published_by,published_at) values ('a18cd2d1-8d19-4b6e-a8d7-d0ca3c9fb605','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-00000005a2a1','1','Training Foundations Check','{"scorePolicy": "highest", "schemaVersion": 1, "passingPercent": 70, "cooldownMinutes": 0}'::jsonb,'[{"id": "723cdd5a-073c-4eda-bffa-1059aaf3414b", "data": {"points": 10, "prompt": "Progressive overload is best described as…", "options": [{"id": "af729d7e-47a9-44c8-8642-2fa27afd004d", "text": "Gradually doing a little more — via load, reps, range, tempo, or quality"}, {"id": "ac0957fd-59c3-4d7a-8450-5e557a47e0f5", "text": "Adding weight every single session"}, {"id": "e41f02dc-aec0-4cd1-b3b6-0293e6aedcee", "text": "Training to failure on everything"}], "correctOptionId": "af729d7e-47a9-44c8-8642-2fa27afd004d"}, "type": "multiple_choice", "position": "a0", "required": true, "schemaVersion": 1}, {"id": "d4b3ced9-4bb1-4946-9fd1-9ba07eea4ac3", "data": {"points": 5, "prompt": "A deload week is a planned lighter week that helps you absorb training.", "correctValue": true}, "type": "true_false", "position": "a1", "required": true, "schemaVersion": 1}, {"id": "5b57a746-52c3-4d0e-8170-fd563cf40a09", "data": {"points": 10, "prompt": "When your technique is breaking down under a weight, the best move is to…", "options": [{"id": "f9958070-5ef6-45d3-ae48-8f6d7ac8e90a", "text": "Reduce the load and own the pattern first"}, {"id": "c5bd80c7-3b09-46e3-a219-971cbd42cfea", "text": "Push through — form does not matter"}, {"id": "2dc0e3c9-d116-4708-a4aa-f4632f7c793e", "text": "Stop training that lift forever"}], "correctOptionId": "f9958070-5ef6-45d3-ae48-8f6d7ac8e90a"}, "type": "multiple_choice", "position": "a2", "required": true, "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:21:28.651012+00') on conflict (id) do nothing;
insert into public.assessment_versions (id,organization_id,assessment_id,version_number,title,settings,items,published_by,published_at) values ('a226ca56-a657-426f-b576-347d5d9458ee','00000000-0000-4000-8000-000000000102','00000000-0000-4000-8000-00000005a3a1','1','Nutrition Foundations Check','{"scorePolicy": "highest", "schemaVersion": 1, "passingPercent": 70, "cooldownMinutes": 0}'::jsonb,'[{"id": "339db66b-4a78-442c-8770-b6c92eb7832a", "data": {"points": 5, "prompt": "Chronic under-eating tends to hurt training quality and recovery.", "correctValue": true}, "type": "true_false", "position": "a0", "required": true, "schemaVersion": 1}, {"id": "11564186-a516-4062-8279-1c7cb9078506", "data": {"points": 10, "prompt": "The most practical protein habit is…", "options": [{"id": "dba42249-adfa-427c-ad48-6900de723961", "text": "A protein source at most meals, spread across the day"}, {"id": "808a08b5-713a-42c4-a6b0-8336ff2be67d", "text": "All your protein in one post-workout shake"}, {"id": "91d8b6a1-9ef4-4981-8157-760a8f5d77ce", "text": "Avoiding protein to save calories"}], "correctOptionId": "dba42249-adfa-427c-ad48-6900de723961"}, "type": "multiple_choice", "position": "a1", "required": true, "schemaVersion": 1}, {"id": "3b344d34-b6be-4be4-a006-f55b349d9043", "data": {"points": 10, "prompt": "At Built For Her, calories are best understood as…", "options": [{"id": "af125af4-1748-458b-94bc-8d8fed273019", "text": "Energy that fuels training and recovery"}, {"id": "d05f62be-65af-448b-be7e-7de130d87ea7", "text": "Something to minimize at all costs"}, {"id": "03f41a59-d247-4ab9-adb4-e5f1cca94b20", "text": "A measure of willpower"}], "correctOptionId": "af125af4-1748-458b-94bc-8d8fed273019"}, "type": "multiple_choice", "position": "a2", "required": true, "schemaVersion": 1}]'::jsonb,'00000000-0000-4000-8000-000000000021','2026-07-30 04:22:42.728718+00') on conflict (id) do nothing;
